import React, {useState, useContext} from 'react';
import {
  MDBBtn,
  MDBContainer,
  MDBCard,
  MDBCardBody,
  MDBCardImage,
  MDBRow,
  MDBCol,
  MDBIcon,
  MDBInput
}
from 'mdb-react-ui-kit';
import { Button, Form } from 'react-bootstrap';

import AuthContext from '../components/AuthContext';

import {Link} from 'react-router-dom'

function LoginScreen() {
  const [email, setEmail]=useState('')
  const [password, setPassword]=useState('')
  const [confirmPassword, setConfirmPassword]=useState('')
  let {loginUser} =useContext(AuthContext)

  return (
    <MDBContainer className="my-5">


      <MDBCard>
        <MDBRow className='g-0'>

          <MDBCol md='6'>
            <MDBCardImage src='https://mdbcdn.b-cdn.net/img/Photos/new-templates/bootstrap-login-form/img1.webp' alt="login form" className='rounded-start w-100'/>
          </MDBCol>
          <MDBCol md='6'>
            <Form className='d-flex flex-column' onSubmit={loginUser}>

              <h5 className="fw-normal my-4 pb-3" style={{letterSpacing: '1px'}}>Sign into your account</h5>

              <Form.Group className="mb-3 me-4" controlId="email">
              <Form.Label className='fw-bold fs-4'>Email</Form.Label>
              <Form.Control wrapperClass='mb-4' type='email' size="lg" value={email} onChange={(e) => setEmail(e.target.value)}/>
              </Form.Group> 

              <Form.Group className="mb-3 me-4" controlId="password">
              <Form.Label className='fw-bold fs-4'>Password</Form.Label>
              <Form.Control wrapperClass='mb-4' type='password' size="lg" value={password} onChange={(e) => setPassword(e.target.value)}/>
              </Form.Group> 

              <Form.Group className="mb-3 me-4" controlId="confirmPassword">
              <Form.Label className='fw-bold fs-4'>Confirm Password</Form.Label>
              <Form.Control wrapperClass='mb-4' type='password' size="lg" value={confirmPassword} onChange={(e) => setsetConfirmPassword(e.target.value)}/>
              </Form.Group> 
                

              <Button className="mb-4 px-5" type='submit' color='dark' size='lg'>Login</Button>
          
              <p className="mb-5 pb-lg-2" style={{color: '#393f81'}}>Don't have an account? <Link to="/register"> <MDBBtn className="px-5" color='dark' size='sm'>Register</MDBBtn> </Link></p>

            </Form>
          </MDBCol>
        </MDBRow>
      </MDBCard>

    </MDBContainer>
  );
}

export default LoginScreen;
